  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    # Build maps
    nodes_by_id = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])

    # Find root
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            break

    # Precompute subtree sets (including self)
    subtree = {}
    def compute_subtree(nid):
        if nid in subtree:
            return subtree[nid]
        s = {nid}
        for cid in children[nid]:
            s.update(compute_subtree(cid))
        subtree[nid] = s
        return s
    for n in nodes:
        compute_subtree(n['id'])

    # Initial retained set
    retained = set(nodes_by_id.keys())

    # Sort nodes: depth descending, id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    removed_order = []

    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        # Cannot remove root
        if nid == root_id:
            continue
        # Cannot remove if not removable
        if not node['removable']:
            continue
        # Never remove a required symbol
        if node['symbol'] in required_symbols:
            continue
        # Cannot remove if any child is still retained
        has_retained_child = any(cid in retained for cid in children[nid])
        if has_retained_child:
            continue
        # Check if any required symbol would be lost entirely after removal of subtree
        sub = subtree[nid]
        loss_possible = False
        for sym in required_symbols:
            # Check if there is still a retained node with this sym outside the subtree
            found_outside = False
            for other_nid in retained:
                if other_nid not in sub and nodes_by_id[other_nid]['symbol'] == sym:
                    found_outside = True
                    break
            if not found_outside:
                loss_possible = True
                break
        if loss_possible:
            continue
        # Remove node
        removed_order.append(nid)
        retained.remove(nid)
        # Descendants already removed (processed deeper first), so no further action needed.

    retained_ids_sorted = sorted(retained)

    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_ids_sorted
    }"
}
